#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct EmitDirective {
    pub severity: DiagnosticSeverity,
    pub message: String,
}

pub fn diagnostic_severity_eq(a: DiagnosticSeverity, b: DiagnosticSeverity) -> bool {
    match a.clone() {
    DiagnosticSeverity::SeverityError => match b.clone() {
    DiagnosticSeverity::SeverityError => true,
    DiagnosticSeverity::SeverityWarning => false,
},
    DiagnosticSeverity::SeverityWarning => match b.clone() {
    DiagnosticSeverity::SeverityError => false,
    DiagnosticSeverity::SeverityWarning => true,
},
}
}

pub fn emit_directive_eq(a: Rc<EmitDirective>, b: Rc<EmitDirective>) -> bool {
    (diagnostic_severity_eq(a.severity.clone(), b.severity.clone()) && (a.message.clone() == b.message.clone()))
}

pub fn equality_derived_correction(a: Rc<Correction>, b: Rc<Correction>) -> bool {
    match (*a.clone()).clone() {
    Correction::Suggested { node: eqa_node, .. } => match (*b.clone()).clone() {
    Correction::Suggested { node: eqb_node, .. } => crate::v2_std_node::node_equal_ignoring_provenance(eqa_node.clone(), eqb_node.clone()),
    _ => false,
},
    Correction::Unavailable { reason: eqa_reason, .. } => match (*b.clone()).clone() {
    Correction::Unavailable { reason: eqb_reason, .. } => (eqa_reason.clone() == eqb_reason.clone()),
    _ => false,
},
}
}

pub fn equality_derived_diagnostic(a: Rc<Diagnostic>, b: Rc<Diagnostic>) -> bool {
    (((a.reason.clone() == b.reason.clone()) && locus_eq(a.at.clone(), b.at.clone())) && equality_derived_correction(a.correction.clone(), b.correction.clone()))
}

pub fn equality_derived_non_empty_diagnostics(a: Rc<NonEmptyDiagnostics>, b: Rc<NonEmptyDiagnostics>) -> bool {
    (equality_derived_diagnostic(a.head.clone(), b.head.clone()) && crate::std_algebra::zip_eq(a.tail.clone(), b.tail.clone(), |eqp0, eqq0| equality_derived_diagnostic(eqp0.clone(), eqq0.clone())))
}

pub fn equality_derived_diagnostics(a: Option<Rc<NonEmptyDiagnostics>>, b: Option<Rc<NonEmptyDiagnostics>>) -> bool {
    match a.clone() {
    std::option::Option::None => match b.clone() {
    std::option::Option::None => true,
    _ => false,
},
    Some(eqa_diagnostics) => match b.clone() {
    Some(eqb_diagnostics) => equality_derived_non_empty_diagnostics(eqa_diagnostics.clone(), eqb_diagnostics.clone()),
    _ => false,
},
}
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct Accumulate;
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct ShortCircuit;
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct SeverityError;
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct SeverityWarning;
